import json,os
from pathlib import Path
from playwright.sync_api import sync_playwright
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page();page.goto(os.environ.get('JACKPOT_QA_URL','http://127.0.0.1:3400')+'/');r=page.evaluate('''async()=>await new Promise((resolve,reject)=>{const w=new Worker('/js/abyss/research-worker.js',{type:'module'});let approximate=false,physics=false;const timer=setTimeout(()=>{w.terminate();reject(new Error('Worker timeout'))},30000);w.onerror=e=>reject(new Error(e.message));w.onmessage=({data:d})=>{if(d.type==='error'){reject(new Error(d.message));return}if(d.id===1&&d.type==='result'){approximate=d.completed===1000;w.postMessage({type:'start',id:2,mode:'physics',trials:1000,seed:'worker-si',difficulty:'easy',power:55,angle:-90,config:{}})}else if(d.id===2&&d.type==='progress'&&d.completed>0){physics=true;w.postMessage({type:'cancel'})}else if(d.type==='cancelled'){clearTimeout(timer);w.terminate();resolve({approximate,physics,cancelled:true,completed:d.completed})}};w.postMessage({type:'start',id:1,mode:'approximate',trials:1000,seed:'worker-si'})})''');assert r['approximate'] and r['physics'] and r['cancelled'];Path('docs/qa/jackpot-si/worker-check.json').write_text(json.dumps(r,indent=2));print(r);b.close()
